const e="12 packs",o=[{id:"snack-survival-basics",packId:"pack-survival-basics",kind:"snack",title:"Survival Basics",shortTitle:"Survival",afterChapter:1,level:"A1",canDo:"Get through the first day politely before you can build long sentences.",index:0,cardCount:12,cards:[{kind:"guess",word:{ko:"안녕하세요",romanization:"annyeonghaseyo",en:"Hello. / Hi.",pos:"expression",nuance:"안녕하세요 is the all-purpose 존댓말 greeting for strangers, coworkers, shopkeepers, teachers — basically any adult you are not on 반말 terms with. The root 안녕(安寧) means 'peace/well-being', so the phrase literally asks 'are you at peace?', but modern Koreans hear it simply as 'hello'; it works morning, noon, and night since Korean has no separate 'good morning/afternoon/evening' equivalents. The register ladder runs: 안녕 (반말, close friends / children / clear juniors) → 안녕하세요 (standard polite) → 안녕하십니까 (격식체, formal broadcasts and service settings). A key social rule: saying 안녕 to a teacher, boss, or older stranger signals either extreme intimacy or disrespect — always default to 안녕하세요 until 반말 is mutually established. The classic English-speaker trap is splitting greetings by time of day or tacking on 어떻게 지내세요? every time — in Korean, 안녕하세요 alone is the complete, natural hello, and opening with a wellbeing question to a stranger sounds oddly probing."},sentence:{ko:"A: 안녕하세요! / B: 네, 안녕하세요.",en:"A: Hello! / B: Yes, hello."},target:"안녕하세요",options:["Thank you.","I'm sorry. / I apologize.","Hello. / Hi."],note:""},{kind:"guess",word:{ko:"감사합니다",romanization:"gamsahamnida",en:"Thank you.",pos:"expression",nuance:"감사합니다 is the default 존댓말 'thank you' safe with literally anyone — a stranger, a clerk, a teacher, your boss — and never wrong. It comes from Sino-Korean 감사(感謝), giving it a slightly formal, composed feel compared to the warmer native alternative 고맙습니다. The formality ladder runs: 고마워 (반말, friends/juniors) → 고마워요 (gentle polite) → 감사합니다 (standard polite) → 대단히 감사합니다 / 감사드립니다 (격식, speeches, written). The nearest alternative is 고맙습니다, which is pure native Korean and sounds a touch warmer and more personal; both are equally polite, and the choice is mostly about tone rather than rank. The classic English-speaker error is stacking a noun directly: you cannot say '도움 감사합니다' as if words simply pile up — to thank for an action you must attach ~아/어 주셔서 (도와주셔서 감사합니다). Another mistake is using 고마워 with strangers or anyone older, which sounds presumptuous and rude."},sentence:{ko:"감사합니다.",en:"Thank you."},target:"감사합니다",options:["Thank you.","Hello. / Hi.","I'm sorry. / I apologize."],note:""},{kind:"guess",word:{ko:"죄송합니다",romanization:"joesonghamnida",en:"I'm sorry. / I apologize.",pos:"expression",nuance:"죄송합니다 is the higher-deference 'I'm sorry', from Sino-Korean 죄송(罪悚), literally 'I feel I have committed a fault and am fearful before you'. That deferential weight makes it the correct apology toward strangers, seniors, customers, and your boss — situations where showing you lower yourself is required. The formality ladder: 미안해 (반말, peers/friends) → 미안해요 (gentle polite) → 죄송해요 / 죄송합니다 (polite, upward-safe) → 대단히 죄송합니다 / 죄송스럽습니다 (격식, serious fault). The dividing line versus 미안하다 is deference: 죄송하다 lowers yourself and is always safe upward; 미안하다 is more horizontal and personal, and sounds too casual to a boss. Three concrete English-speaker mistakes: (1) attaching the reason wrong — use X-아/어서 죄송합니다 (늦어서 죄송합니다), not '늦은 것 죄송'; (2) using 미안해 to a boss or stranger; (3) confusing it with 실례합니다, which is 'excuse me' for a small intrusion, not an apology for fault."},sentence:{ko:"죄송합니다.",en:"I'm sorry."},target:"죄송합니다",options:["I'm sorry. / I apologize.","Hello. / Hi.","Thank you."],note:""},{kind:"guess",word:{ko:"네",romanization:"ne",en:"Yes.",pos:"expression",nuance:"네 can also mean “I hear you” or “okay” while listening, not only yes."},sentence:{ko:"네.",en:"Yes."},target:"네",options:["Hello. / Hi.","Thank you.","Yes."],note:""},{kind:"guess",word:{ko:"아니요",romanization:"aniyo",en:"No.",pos:"expression",nuance:"Use 아니요 as a polite no. 아니 is casual, and 아니요 often sounds softer when followed by a short explanation like 괜찮아요 or 몰라요."},sentence:{ko:"아니요.",en:"No."},target:"아니요",options:["No.","Hello. / Hi.","Thank you."],note:""},{kind:"guess",word:{ko:"괜찮아요",romanization:"gwaenchanayo",en:"It's okay. / That's all right. / No, thank you.",pos:"expression"},sentence:{ko:"A: 죄송해요. / B: 괜찮아요, 그럴 수도 있죠.",en:"A: I'm sorry. / B: It's okay, these things happen."},target:"괜찮아요",options:["It's okay. / That's all right. / No, thank you.","Hello. / Hi.","I'm sorry. / I apologize."],note:""},{kind:"guess",word:{ko:"안녕히 가세요",romanization:"annyeonghi gaseyo",en:"Goodbye (to someone who is leaving).",pos:"expression"},sentence:{ko:"A: 이제 가 볼게요. / B: 네, 안녕히 가세요.",en:"A: I'll head off now. / B: Take care, goodbye."},target:"안녕히 가세요",options:["Hello. / Hi.","Goodbye (to someone who is leaving).","Thank you."],note:""},{kind:"guess",word:{ko:"안녕히 계세요",romanization:"annyeonghi gyeseyo",en:"Goodbye (said by the person who is leaving).",pos:"expression",nuance:"안녕히 계세요 is the mirror image of 안녕히 가세요: you say it when YOU are the one leaving and the other person STAYS. The pivot is the verb — 계시다 is the honorific of 있다 'to be/remain (of a person)', so 계세요 wishes the one staying to 'remain in peace'. Both phrases share the same 안녕(安寧) 'peace' root; the verb alone signals direction. English speakers reliably swap the two because 'goodbye' has no who-moves information — the one-second fix is: if my feet are moving, use 계세요; if their feet are moving, use 가세요. A smooth social move before departing is to add 먼저 갈게요 or 먼저 가 볼게요 ('I'll head off first') so leaving ahead of others doesn't seem abrupt or rude. When leaving a workplace where colleagues are still working, pairing 안녕히 계세요 with 수고하세요 ('keep up the good work') is the natural and considerate exit. Formal register: 안녕히 계십시오."},sentence:{ko:"A: 먼저 가겠습니다. 안녕히 계세요. / B: 네, 안녕히 가세요.",en:"A: I'll be heading off now. Goodbye (stay well). / B: Take care, goodbye."},target:"안녕히 계세요",options:["Goodbye (said by the person who is leaving).","Hello. / Hi.","Thank you."],note:""},{kind:"guess",word:{ko:"여기요",romanization:"yeogiyo",en:"Excuse me! (calling the server)",pos:"expression"},sentence:{ko:"여기요!",en:"Excuse me!"},target:"여기요",options:["Hello. / Hi.","Excuse me! (calling the server)","Thank you."],note:""},{kind:"guess",word:{ko:"잠깐만요",romanization:"jamkkanmanyo",en:"Hold on a sec",pos:"expression"},sentence:{ko:"잠깐만요!",en:"Hold on a sec!"},target:"잠깐만요",options:["Hello. / Hi.","Thank you.","Hold on a sec"],note:""},{kind:"guess",word:{ko:"실례합니다",romanization:"sillyehamnida",en:"Excuse me.",pos:"expression"},sentence:{ko:"실례합니다, 화장실이 어디예요?",en:"Excuse me, where's the restroom?"},target:"실례합니다",options:["Excuse me.","Hello. / Hi.","Thank you."],note:""},{kind:"guess",word:{ko:"맞아요",romanization:"majayo",en:"That's right / You're right.",pos:"expression"},sentence:{ko:"A: 이 길로 가면 돼요? / B: 네, 맞아요.",en:"A: Do we go this way? / B: Yes, that's right."},target:"맞아요",options:["Hello. / Hi.","That's right / You're right.","Thank you."],note:""}]},{id:"snack-survival-help",packId:"pack-survival-help",kind:"snack",title:"Survival Help",shortTitle:"Help",afterChapter:2,level:"A1",canDo:"Stay calm when you do not understand, need help, or need one practical sentence fast.",index:0,cardCount:10,cards:[{kind:"guess",word:{ko:"잘 모르겠어요",romanization:"jal moreugesseoyo",en:"I'm not sure / I don't really know.",pos:"expression"},sentence:{ko:"A: 이거 어디다 두면 돼요? / B: 저도 잘 모르겠어요. 사장님한테 물어봐야 할 것 같아요.",en:"A: Where should I put this? / B: I'm not sure either. I think we need to ask the boss."},target:"잘 모르겠어요",options:["I'm not sure / I don't really know.","Please speak slowly","Please say it again."],note:""},{kind:"guess",word:{ko:"한국어를 잘 못해요",romanization:"hangugeoreul jal motaeyo",en:"I'm not good at Korean.",pos:"expression",nuance:"한국어를 잘 못해요 = 한국어 (Korean language) + 를 (object marker) + 잘 (well) + 못하다 (to be unable to do well). The key interpretive point: 잘 못하다 means 'can't do it well' (ability is limited), while 안 하다 means 'I don't do it' (by choice). Using 안 하다 — 한국어를 안 해요 — implies you are refusing or unwilling, which is not what you mean. The 잘 softens the claim from 'I can't speak Korean at all' (한국어 못해요) to 'I'm not good at it', which is more accurate and humble. 한국어 is the neutral/formal word for the language, while 한국말 is more colloquial and warm; both are correct. The classic follow-up toolkit: 천천히 말씀해 주세요 ('please speak slowly'), 다시 한 번 말씀해 주시겠어요? ('could you say that again?'), and 영어 하시는 분 계세요? ('is there anyone who speaks English?'). English speakers most often get the particle wrong (한국어가 잘 못해요 — the language is the object, not the subject) or write 잘못해요 as one word, which means 'to do something wrong/make a mistake' — a completely different word."},sentence:{ko:"죄송해요, 한국어를 잘 못해요.",en:"I'm sorry, I'm not good at Korean."},target:"한국어를 잘 못해요",options:["I'm not good at Korean.","Please speak slowly","Please say it again."],note:""},{kind:"guess",word:{ko:"천천히 말해 주세요",romanization:"cheoncheonhi malhae juseyo",en:"Please speak slowly",pos:"expression"},sentence:{ko:"죄송한데 천천히 말해 주세요.",en:"Sorry, please speak slowly."},target:"천천히 말해 주세요",options:["I'm not sure / I don't really know.","I'm not good at Korean.","Please speak slowly"],note:""},{kind:"guess",word:{ko:"다시 말해 주세요",romanization:"dasi malhae juseyo",en:"Please say it again.",pos:"expression"},sentence:{ko:"다시 말해 주세요.",en:"Please say it again."},target:"다시 말해 주세요",options:["I'm not sure / I don't really know.","I'm not good at Korean.","Please say it again."],note:""},{kind:"guess",word:{ko:"영어 할 수 있어요?",romanization:"yeongeo hal su isseoyo",en:"Can you speak English?",pos:"expression"},sentence:{ko:"영어 할 수 있어요?",en:"Can you speak English?"},target:"영어 할 수 있어요?",options:["Can you speak English?","I'm not sure / I don't really know.","I'm not good at Korean."],note:""},{kind:"guess",word:{ko:"얼마예요?",romanization:"eolmayeyo?",en:"How much is it?",pos:"expression"},sentence:{ko:"A: 얼마예요? / B: 4,500원입니다.",en:"A: How much is it? / B: It's 4,500 won."},target:"얼마예요?",options:["I'm not sure / I don't really know.","I'm not good at Korean.","How much is it?"],note:""},{kind:"guess",word:{ko:"이거 주세요",romanization:"igeo juseyo",en:"I'll have this one, please",pos:"expression"},sentence:{ko:"이거 주세요.",en:"This one, please."},target:"이거 주세요",options:["I'm not sure / I don't really know.","I'm not good at Korean.","I'll have this one, please"],note:""},{kind:"guess",word:{ko:"도와주세요",romanization:"dowajuseyo",en:"Please help me.",pos:"expression"},sentence:{ko:"도와주세요.",en:"Please help me."},target:"도와주세요",options:["I'm not sure / I don't really know.","I'm not good at Korean.","Please help me."],note:""},{kind:"guess",word:{ko:"화장실이 어디예요?",romanization:"hwajangsiri eodiyeyo?",en:"Where is the restroom?",pos:"expression"},sentence:{ko:"화장실이 어디예요?",en:"Where is the restroom?"},target:"화장실이 어디예요?",options:["I'm not sure / I don't really know.","I'm not good at Korean.","Where is the restroom?"],note:""},{kind:"guess",word:{ko:"잠시만요",romanization:"jamsimanyo",en:"One moment, please.",pos:"expression",nuance:"More polite than 잠깐만요. Very useful in stores, offices, and classrooms."},sentence:{ko:"잠시만요.",en:"One moment, please."},target:"잠시만요",options:["I'm not sure / I don't really know.","I'm not good at Korean.","One moment, please."],note:""}]},{id:"snack-numbers",packId:"pack-numbers",kind:"snack",title:"Numbers Starter",shortTitle:"Numbers",afterChapter:3,level:"A1",canDo:"Read prices, counts, simple dates, and clock-hour basics without waiting for a full number chapter.",index:0,cardCount:23,cards:[{kind:"guess",word:{ko:"하나",romanization:"hana",en:"one (native number)",pos:"noun",nuance:'하나 is the native-Korean (고유어) word for "one," the counting system Koreans use for tangible things, people, age, and the clock hour — as opposed to its Sino-Korean twin 일, which rules dates, money, minutes, and phone numbers. The single biggest fact to internalize: when 하나 sits directly in front of a counter (개, 명, 시, 살, 마리), it loses its last syllable and becomes 한 — 한 개, 한 명, 한 시 — while the full 하나 only stands alone (as in counting "하나, 둘" or taking a particle, 하나만). English speakers reliably trip here by saying 하나 개 or, worse, importing the Sino number and saying 일 개; both sound clearly wrong to a Korean ear. There is no hanja because it is purely native, so do not look for one.'},sentence:{ko:"하나, 둘, 셋!",en:"One, two, three!"},target:"하나",options:["one (native number)"],note:""},{kind:"guess",word:{ko:"둘",romanization:"dul",en:"two (native number)",pos:"noun",nuance:`둘 is native-Korean "two," used for counting concrete things, people, and the clock hour, in contrast to Sino 이 which handles minutes, money, floors, and dates. Like 하나→한, 둘 contracts before a counter, dropping its final ㄹ to become 두: 두 개, 두 시, 두 명, 두 잔. The bare 둘 survives only when it stands alone or takes a particle — note the very common 둘 다 ('both') and 둘 중에 ('between the two'). English speakers often forget the contraction and say 둘 개, or reach for the Sino 이 (이 개), both of which sound off; they also tend to say 두 다 by mistake, but the fixed idiom is 둘 다. It is a pure native word, so it has no hanja.`},sentence:{ko:"둘 중에 뭐가 더 좋아요?",en:"Which of the two do you like more?"},target:"둘",options:["two (native number)"],note:""},{kind:"guess",word:{ko:"셋",romanization:"set",en:"three (native number)",pos:"noun",nuance:`셋 is native-Korean "three," the form used to count objects, people, and the clock hour, while Sino 삼 covers minutes, money, dates, and floors. Before a counter it contracts to 세 (세 개, 세 시, 세 명, 세 권), and the bare 셋 only appears standalone, with a particle, or in the social phrase 셋이서 ('as three people together'). A frequent English-speaker error is leaving it uncontracted as 셋 개 or borrowing Sino 삼 개; both are immediately wrong to natives. Another subtle pitfall: 세 (three) and 네 (four) look and sound similar, so learners mix them up — keep 세=3, 네=4 firmly apart. 셋 is purely native and has no hanja.`},sentence:{ko:"셋까지 셀게요. 하나, 둘, 셋!",en:"I'll count to three. One, two, three!"},target:"셋",options:["three (native number)"],note:""},{kind:"guess",word:{ko:"넷",romanization:"net",en:"four (native number)",pos:"noun"},sentence:{ko:"여기 의자가 넷 있어요.",en:"There are four chairs here."},target:"넷",options:["four (native number)"],note:""},{kind:"guess",word:{ko:"다섯",romanization:"daseot",en:"five (native number)",pos:"noun"},sentence:{ko:"다섯까지 셀 수 있어요.",en:"I can count to five."},target:"다섯",options:["five (native number)"],note:""},{kind:"guess",word:{ko:"여섯",romanization:"yeoseot",en:"six (native number)",pos:"noun"},sentence:{ko:"사탕이 여섯 개 있어요.",en:"There are six pieces of candy."},target:"여섯",options:["six (native number)"],note:""},{kind:"guess",word:{ko:"일곱",romanization:"ilgop",en:"seven (native number)",pos:"noun"},sentence:{ko:"무지개는 색깔이 일곱 개예요.",en:"A rainbow has seven colors."},target:"일곱",options:["seven (native number)"],note:""},{kind:"guess",word:{ko:"여덟",romanization:"yeodeolb",en:"eight (native number)",pos:"noun"},sentence:{ko:"거미는 다리가 여덟 개예요.",en:"A spider has eight legs."},target:"여덟",options:["eight (native number)"],note:""},{kind:"guess",word:{ko:"아홉",romanization:"ahop",en:"nine (native number)",pos:"noun"},sentence:{ko:"고양이가 아홉 마리 있어요.",en:"There are nine cats."},target:"아홉",options:["nine (native number)"],note:""},{kind:"guess",word:{ko:"열",romanization:"yeol",en:"ten (native number)",pos:"noun",nuance:"열 (熱, the hanja for 'heat') is a fever, and the must-learn collocation is 열이 나다, where 나다 literally means '(something) comes out/arises' — Korean conceives a fever as heat 'coming out' of the body, so you never say 열을 가지다 ('have/possess a fever'), a direct translation of English 'have' that sounds completely unnatural. You can also say 열이 있다 ('there is fever') as a calmer alternative. The level of a fever is described with 높다/낮다 (열이 높다 = high fever), not 크다/작다, and once treated, 열이 내리다 ('the fever comes down') is the natural way to say it subsides — paralleling how prices or temperature 내리다. To take someone's temperature is 열을 재다 (재다 = to measure), the same verb as 키를 재다 (measure height). Don't confuse this 열 with the homonym 열 meaning 'ten' (열 개 = ten items); context separates them."},sentence:{ko:"열까지 세고 눈을 떠요.",en:"Count to ten and open your eyes."},target:"열",options:["ten (native number)"],note:""},{kind:"guess",word:{ko:"일",romanization:"il",en:"one (Sino number)",pos:"noun",nuance:`일 is the Sino-Korean (漢字語) number "one," from the hanja 一 (a single horizontal stroke). It governs the abstract/measured world: dates, money (원), minutes, phone numbers, floors, bus and problem numbers, and any count from the hundreds up — the exact opposite of native 하나, which counts tangible things, people, and the clock hour. So one o'clock is 한 시 but one minute is 일 분; one apple is 사과 한 개 but one won is 일 원. English speakers, used to a single set of numbers, constantly blur the line — saying 일 시 for one o'clock or 하나 분 for one minute. A handy memory hook: anything that already feels like a 'code' or a 'measurement' (clock minutes, addresses, prices) is Sino 일.`},sentence:{ko:"제 번호는 공일공이에요.",en:"My number starts with 010."},target:"일",options:["one (Sino number)"],note:""},{kind:"guess",word:{ko:"이",romanization:"i",en:"two (Sino number)",pos:"noun",nuance:`이 is the Sino-Korean number "two," from the hanja 二 (two horizontal strokes). It runs dates, money, minutes, floors, math, and counts in the hundreds and up — versus native 둘/두, which counts physical things, people, and the clock hour. So two o'clock is 두 시 but two minutes is 이 분; two cups is 두 잔 but two won is 이 원. A real trap unique to 이: it is identical in sound to the demonstrative 이 ('this') and the subject/topic particle context around it, so 이 분 can mean either 'two minutes' or 'this person' (분 = honorific 'person') depending on context — listen carefully. English speakers also tend to use native 둘 for prices or floors (둘 층); those are Sino: 이 층. Treat measured, coded things as Sino 이.`},sentence:{ko:"이 더하기 이는 사예요.",en:"Two plus two is four."},target:"이",options:["two (Sino number)"],note:""},{kind:"guess",word:{ko:"삼",romanization:"sam",en:"three (Sino number)",pos:"noun",nuance:`삼 is the Sino-Korean number "three," from the hanja 三 (three horizontal strokes). It governs dates, money, minutes, floors, arithmetic, and larger counts — in contrast to native 셋/세, which counts tangible objects, people, and the clock hour. So three o'clock is 세 시 but three minutes is 삼 분; three notebooks is 세 권 but 30,000 won is 삼만 원. The recurring English-speaker mistake is using 삼 to tell the hour (삼 시) or reaching for native 세 in a price (세만 원). A useful anchor: cooking and timer durations in minutes are always Sino, so '3 minutes' on a ramen pack is 삼 분, never 세 분. Keep measured/coded contexts on the Sino side, 삼.`},sentence:{ko:"삼 곱하기 삼은 구예요.",en:"Three times three is nine."},target:"삼",options:["three (Sino number)"],note:""},{kind:"guess",word:{ko:"사",romanization:"sa",en:"four (Sino number)",pos:"noun"},sentence:{ko:"사월에 벚꽃이 펴요.",en:"Cherry blossoms bloom in April."},target:"사",options:["four (Sino number)"],note:""},{kind:"guess",word:{ko:"오",romanization:"o",en:"five (Sino number)",pos:"noun"},sentence:{ko:"오 더하기 오는 십이에요.",en:"Five plus five is ten."},target:"오",options:["five (Sino number)"],note:""},{kind:"guess",word:{ko:"육",romanization:"yuk",en:"six (Sino number)",pos:"noun"},sentence:{ko:"육 곱하기 이는 십이예요.",en:"Six times two is twelve."},target:"육",options:["six (Sino number)"],note:""},{kind:"guess",word:{ko:"칠",romanization:"chil",en:"seven (Sino number)",pos:"noun"},sentence:{ko:"칠 빼기 이는 오예요.",en:"Seven minus two is five."},target:"칠",options:["seven (Sino number)"],note:""},{kind:"guess",word:{ko:"팔",romanization:"pal",en:"eight (Sino number)",pos:"noun"},sentence:{ko:"팔 더하기 이는 십이에요.",en:"Eight plus two is ten."},target:"팔",options:["eight (Sino number)"],note:""},{kind:"guess",word:{ko:"구",romanization:"gu",en:"nine (Sino number)",pos:"noun"},sentence:{ko:"구 더하기 일은 십이에요.",en:"Nine plus one is ten."},target:"구",options:["nine (Sino number)"],note:""},{kind:"guess",word:{ko:"십",romanization:"sip",en:"ten (Sino number)",pos:"noun"},sentence:{ko:"십까지 세어 볼까요?",en:"Shall we count to ten?"},target:"십",options:["ten (Sino number)"],note:""},{kind:"guess",word:{ko:"백",romanization:"baek",en:"(one) hundred (Sino number)",pos:"noun"},sentence:{ko:"백 원짜리 동전 있어요?",en:"Do you have a 100-won coin?"},target:"백",options:["(one) hundred (Sino number)"],note:""},{kind:"guess",word:{ko:"천",romanization:"cheon",en:"(one) thousand (Sino number)",pos:"noun"},sentence:{ko:"천 원만 빌려줘.",en:"Lend me just a thousand won."},target:"천",options:["(one) thousand (Sino number)"],note:""},{kind:"guess",word:{ko:"만",romanization:"man",en:"ten thousand (Sino number)",pos:"noun"},sentence:{ko:"이거 만 원이에요.",en:"This is ten thousand won."},target:"만",options:["ten thousand (Sino number)"],note:""}]},{id:"snack-family",packId:"pack-family",kind:"snack",title:"Family Words",shortTitle:"Family",afterChapter:2,level:"A1",canDo:"Name close people naturally when introducing yourself or asking about someone.",index:0,cardCount:14,cards:[{kind:"guess",word:{ko:"가족",romanization:"gajok",en:"family",pos:"noun",nuance:"가족 is the Sino-Korean word 家族 ('house' 家 + 'clan/group' 族), so it names the whole family unit as a collective, never a single relative — for one member you must say 가족 한 명 or name the relationship (형, 누나). The near-synonym 식구 also means family but literally means 食口 'mouths to feed', stressing the people who live and eat under one roof, so 식구 feels warmer and more domestic ('우리 식구 다섯이에요') while 가족 is the neutral standard term that also covers relatives living apart. Register is neutral and safe in any setting. The big English-speaker trap is two-fold: 'big/small family' is 가족이 많다/적다 (many/few), never 가족이 크다 (that sounds like physically large bodies); and Koreans say 우리 가족 ('our family') where English forces 'my family', so the 우리 is idiomatic, not a mistake."},sentence:{ko:"우리 가족은 네 명이에요.",en:"My family has four people."},target:"가족",options:["mom","dad","family"],note:""},{kind:"guess",word:{ko:"엄마",romanization:"eomma",en:"mom",pos:"noun"},sentence:{ko:"우리 엄마는 요리를 잘해요.",en:"My mom cooks well."},target:"엄마",options:["family","dad","mom"],note:""},{kind:"guess",word:{ko:"아빠",romanization:"appa",en:"dad",pos:"noun"},sentence:{ko:"우리 아빠는 회사에 다녀요.",en:"My dad works at a company."},target:"아빠",options:["family","mom","dad"],note:""},{kind:"guess",word:{ko:"어머니",romanization:"eomeoni",en:"mother",pos:"noun",nuance:"어머니 is the respectful, neutral word for 'mother,' used in polite speech, in writing, and when talking about your mom to others. Its near-synonym 엄마 is the affectionate home word ('mom/mommy') that people usually call her directly at home, while 어머니 carries more formality and respect — the same distance as English 'mom' vs 'mother.' The higher honorific 어머님 is for someone else's mother or your mother-in-law. As an elder, 어머니 routinely takes honorific particles and endings: 께서 for the subject, 께 for 'to,' and -(으)시- verbs (하세요, 주무세요). Watch two English-speaker traps: the copula contracts to 어머니예요 after the vowel 니 (not '어머니이에요'); and you give things to her with the honorific 어머니께 ... 드리다, not the plain 어머니한테 ... 줘요. Possession is likewise 우리 어머니, since 내 어머니 sounds unnaturally distant."},sentence:{ko:"우리 어머니는 선생님이에요.",en:"My mother is a teacher."},target:"어머니",options:["mother","family","mom"],note:""},{kind:"guess",word:{ko:"아버지",romanization:"abeoji",en:"father",pos:"noun",nuance:"아버지 is the respectful, neutral word for 'father,' used in polite conversation, in writing, and whenever you speak about your dad to others. Its near-synonym 아빠 is the warm home word ('dad/daddy'): children and many adults call him 아빠 to his face, while 아버지 sounds more grown-up, dignified, or formal — the gap is exactly the English 'dad' vs 'father.' One step higher is 아버님, reserved for someone else's father or your father-in-law. Because a father is an elder, 아버지 naturally pulls honorific machinery: the subject marker 께서, the dative 께, and -(으)시- verb endings (읽으세요, 주무세요). Two English-speaker pitfalls: the copula is 아버지예요 (vowel-final 지 → 예요, not '아버지이에요'); and possession uses 우리 아버지 ('our father'), since 내 아버지 sounds oddly cold to Korean ears."},sentence:{ko:"우리 아버지는 회사원이에요.",en:"My father is an office worker."},target:"아버지",options:["father","family","mom"],note:""},{kind:"guess",word:{ko:"언니",romanization:"eonni",en:"older sister (female speaker)",pos:"noun",nuance:"언니 is the word a FEMALE uses for an older sister, and it extends warmly to any close older woman — an older female friend, a senior at school or work — and is also the friendly way younger women address a female shopkeeper or restaurant server ('언니, 여기요!'), so it ranges from blood sister to polite stranger. Its gendered counterpart is 누나, used by a MALE for the same older-sister bond, so 언니 vs 누나 splits purely by the speaker's gender, and the word reveals that the speaker is a woman — a distinction English 'older sister' simply lacks. Register is casual and affectionate, used with -요 endings, and 언니 itself serves as the address (you say 언니, not her name). The chief English-speaker pitfall is gender: a man must say 누나, never 언니, for an older sister; and don't be surprised to hear women call a saleswoman 언니 — it is friendly social lubricant, not a claim of kinship."},sentence:{ko:"저는 언니가 두 명 있어요.",en:"I have two older sisters."},target:"언니",options:["family","older sister (female speaker)","mom"],note:""},{kind:"guess",word:{ko:"오빠",romanization:"oppa",en:"older brother (female speaker)",pos:"noun",nuance:"오빠 is the word a FEMALE uses for an older brother, and it is the most socially loaded kinship term in Korean: a woman also calls a close older male friend, a senior, or especially a boyfriend 오빠, so '오빠' on its own can mean 'my big brother', 'my guy friend', or 'babe' depending on context — hence 친오빠 exists to specify the actual sibling. Its gendered counterpart is 형, used by a MALE for the same older-brother relationship, so 오빠 vs 형 splits by speaker, and the word instantly reveals the speaker is a woman. Register is casual and affectionate, used with -요 forms, and 오빠 is itself the address term (never his bare name). The major English-speaker pitfall is gender — a man must say 형, never 오빠 — and the cultural trap: because 오빠 also means 'boyfriend' in romantic use, calling a male friend 오빠 can imply flirtation, so learners should know the connotation before using it freely."},sentence:{ko:"저는 오빠가 한 명 있어요.",en:"I have one older brother."},target:"오빠",options:["family","mom","older brother (female speaker)"],note:""},{kind:"guess",word:{ko:"누나",romanization:"nuna",en:"older sister (male speaker)",pos:"noun",nuance:"누나 is the word a MALE uses for an older sister, and like 형 it doubles as a warm address title a younger man uses for any older woman he is close to — an older female friend, senior student, or, famously, a beloved older woman ('누나' in K-pop). Its gendered partner is 언니, which a FEMALE uses for the very same older-sister relationship, so 누나 vs 언니 is split purely by who is speaking, and the word betrays the speaker's gender in a way English 'older sister' cannot. Register is casual but deferential: 누나 is itself a respectful address (you call her 누나, not her name) and you speak up to her with -요 forms. A very natural collocation is 도와주다 'help (as a favor)'. The headline English-speaker pitfall is gender: a man must say 누나 and a woman 언니 for an older sister — swapping them is an immediate giveaway — and remember 누나 is also how a younger man fondly addresses an older woman, not only a sibling."},sentence:{ko:"저는 누나가 두 명 있어요.",en:"I have two older sisters."},target:"누나",options:["family","mom","older sister (male speaker)"],note:""},{kind:"guess",word:{ko:"형",romanization:"hyeong",en:"older brother (male speaker)",pos:"noun",nuance:"형 (Sino-Korean 兄 'elder brother') is the word a MALE uses for an older brother, and crucially it is also a warm address term a younger man uses for any slightly-older male he is close to — an older friend, schoolmate, or colleague — so '민수 형' can mean 'Minsu, my big-brother-figure', not a blood relative. The matched set is gendered by speaker: a female says 오빠 for the same older-brother relationship, while 누나/언니 cover older sisters — so the single word leaks the speaker's gender, something English's flat 'older brother' never does. Register is casual-but-respectful: 형 is itself an honorific address (you call him 형, never his bare name), and you speak up to him. The dominant English-speaker pitfall is gender: a woman must never call her older brother 형 — that is 오빠 — and second, don't assume 형 always means kin; in daily life it is most often the affectionate title for an older male friend."},sentence:{ko:"저는 형이 한 명 있어요.",en:"I have one older brother."},target:"형",options:["family","mom","older brother (male speaker)"],note:""},{kind:"guess",word:{ko:"동생",romanization:"dongsaeng",en:"younger sibling",pos:"noun",nuance:"동생 (Sino-Korean 同生 'born of the same' parents) means a younger sibling and, unlike the older-sibling words, is NOT split by speaker gender and does NOT itself reveal whether the sibling is male or female — to specify you prepend 남 (男) for 남동생 'younger brother' or 여 (女) for 여동생 'younger sister'. It also extends to any younger person you are close to (a junior at work or school), mirroring how 형/오빠/누나/언니 work upward; the system is asymmetric — elders get gendered, speaker-dependent titles, while juniors share the one neutral 동생. Register: unlike the older-sibling titles, 동생 is NOT used as a direct address — you call a younger sibling by name, and 동생 is only how you refer to them. The key English-speaker pitfall is assuming 동생 means 'younger brother'; it is sex-neutral, so without 남/여 it could be either, and you should never address someone as '동생' the way you'd say '형' — call them by name instead."},sentence:{ko:"저는 동생이 한 명 있어요.",en:"I have one younger sibling."},target:"동생",options:["family","mom","younger sibling"],note:""},{kind:"guess",word:{ko:"할머니",romanization:"halmeoni",en:"grandmother",pos:"noun",nuance:"할머니 is your grandmother on either side, and in plain conversation Koreans use it for both the father's and the mother's mother; add 외- (외할머니) or 친- (친할머니) only when you must mark the side. It is built from 할- (an old prefix meaning a generation above) + 어머니 'mother', and it doubles as a warm, respectful way to address ANY elderly woman you feel close to, much like English 'grandma' for a kindly neighbor. The big trap for English speakers is grammar of respect, not vocabulary: a grandmother is a high-status elder, so the verb itself must be honorific — say 할머니는 사세요 / 주무세요 / 드세요, never the flat 살아요 / 자요 / 먹어요. Pair it with 우리 할머니 ('our grandmother'), not 제 할머니, because Korean treats family as shared. Compared with the polite stranger-address 아주머니/아주머님 (a middle-aged woman), 할머니 implies real old age, so misjudging the age can sting."},sentence:{ko:"할머니, 안녕히 주무세요.",en:"Grandmother, sleep well (good night)."},target:"할머니",options:["family","mom","grandmother"],note:""},{kind:"guess",word:{ko:"할아버지",romanization:"harabeoji",en:"grandfather",pos:"noun",nuance:"할아버지 is your grandfather on either side, and casual speech uses it for both the father's and the mother's father; 외할아버지 (maternal) or 친할아버지 (paternal) pin down the side when it matters. It is 할- (a prefix for the generation above) + 아버지 'father', and like 할머니 it can respectfully address any elderly man you know. The spelling trips beginners because of the liaison: it is one solid word, 할아버지, written together — never 할 아버지 — and the ㄹ slides onto the next syllable so it sounds like 하라버지. The deeper pitfall for English speakers is honorifics: a grandfather outranks you, so the verb climbs to the honorific level (읽으세요, 주무세요, 진지 드세요), and 밥 politely becomes 진지. Say 우리 할아버지, mirroring 우리 할머니, rather than the textbook-literal 제 할아버지."},sentence:{ko:"할아버지, 진지 드세요.",en:"Grandfather, please eat (your meal)."},target:"할아버지",options:["grandfather","family","mom"],note:""},{kind:"guess",word:{ko:"아들",romanization:"adeul",en:"son",pos:"noun"},sentence:{ko:"저는 아들이 한 명 있어요.",en:"I have one son."},target:"아들",options:["family","mom","son"],note:""},{kind:"guess",word:{ko:"딸",romanization:"ttal",en:"daughter",pos:"noun"},sentence:{ko:"저는 딸이 두 명 있어요.",en:"I have two daughters."},target:"딸",options:["daughter","family","mom"],note:""}]},{id:"snack-body",packId:"pack-body",kind:"snack",title:"Body Basics",shortTitle:"Body",afterChapter:3,level:"A1",canDo:"Say what hurts, describe people, and understand basic health phrases.",index:0,cardCount:16,cards:[{kind:"guess",word:{ko:"몸",romanization:"mom",en:"body",pos:"noun",nuance:"몸 is the physical body taken as a whole, and crucially it's also the word Koreans reach for to describe how they FEEL: 몸이 아파요 (sick) and 몸이 안 좋아요 (off/unwell) are the everyday health phrases. The near-synonym is the Sino-Korean 신체(身體, 'body-substance'), but 신체 is clinical/official — 신체검사 (physical exam), 신체 활동 (physical activity) — and sounds stiff if you use it about yourself, so say 몸. Habitual collocations: 몸이 아프다, 몸이 안 좋다, 몸이 피곤하다, 몸이 무겁다, 몸조심하다, 몸이 약하다 (to have a weak constitution). The big English-speaker pitfall is the particle and the verb: you say 몸이 아프다 ('the body is sick'), so the body is the SUBJECT (이/가) — never 몸을 아파요. Also don't directly translate 'my body is heavy' as a weight statement; 몸이 무겁다 means you feel sluggish/lethargic, not that you weigh a lot."},sentence:{ko:"오늘은 몸이 좀 피곤해요.",en:"I'm a bit tired today."},target:"몸",options:["head; also hair","face","body"],note:""},{kind:"guess",word:{ko:"머리",romanization:"meori",en:"head; also hair",pos:"noun"},sentence:{ko:"머리가 아파요.",en:"My head hurts."},target:"머리",options:["body","face","head; also hair"],note:""},{kind:"guess",word:{ko:"얼굴",romanization:"eolgul",en:"face",pos:"noun"},sentence:{ko:"언니 얼굴이 정말 예뻐요.",en:"My older sister's face is really pretty."},target:"얼굴",options:["face","body","head; also hair"],note:""},{kind:"guess",word:{ko:"눈",romanization:"nun",en:"eye",pos:"noun",nuance:"눈 is the eye, but the identical spelling also means 'snow'; the two are split by pitch (eye = short/low, snow = long/high) and above all by context, so listeners rarely confuse them. Korean treats the pair of eyes as one uncountable 눈, so you never pluralize it. The big English-speaker trap is eyesight: vision is rated with 좋다 (good) and 나쁘다 (bad) — 눈이 좋아요 / 눈이 나빠요 — never with 'strong/weak' (강하다/약하다), which would sound bizarre. Note that 눈을 감다 uses the same 감다 as washing hair but means 'close', and the related verb 보다 ('see/look') is what the eye does, while 만나다 ('meet') is for people, so don't blend them."},sentence:{ko:"눈이 아파요.",en:"My eyes hurt."},target:"눈",options:["body","eye","head; also hair"],note:""},{kind:"guess",word:{ko:"코",romanization:"ko",en:"nose",pos:"noun"},sentence:{ko:"코가 막혀요.",en:"My nose is stuffy."},target:"코",options:["body","head; also hair","nose"],note:""},{kind:"guess",word:{ko:"입",romanization:"ip",en:"mouth",pos:"noun"},sentence:{ko:"입을 크게 벌리세요.",en:"Open your mouth wide."},target:"입",options:["mouth","body","head; also hair"],note:""},{kind:"guess",word:{ko:"귀",romanization:"gwi",en:"ear",pos:"noun"},sentence:{ko:"귀가 아파요.",en:"My ear hurts."},target:"귀",options:["body","ear","head; also hair"],note:""},{kind:"guess",word:{ko:"목",romanization:"mok",en:"neck; throat",pos:"noun",nuance:"목 covers both the neck and the throat, so 목이 아프다 most often means a sore throat from a cold, NOT neck pain — assuming it only means 'neck' is the main English-speaker pitfall (for true neck/shoulder stiffness Koreans more often say 목이 뻐근하다 or specify 목덜미). Thirst is the fixed phrase 목이 마르다 ('the throat dries'), where 마르다 is 르-irregular → 말라요, 말랐어요; do not invent 목이 건조하다. A swollen throat is 목이 붓다 (ㅅ-irregular → 부어요), the same swelling verb as 발이 붓다, and going hoarse is 목이 쉬다 (lit. 'the throat rests'). Idiomatically 목이 빠지게 기다리다 means to wait so eagerly your neck stretches out ('wait with bated breath'). A throat/neck symptom marks the part with 가 (목이 아파요)."},sentence:{ko:"목이 아파요.",en:"My throat hurts."},target:"목",options:["body","neck; throat","head; also hair"],note:""},{kind:"guess",word:{ko:"어깨",romanization:"eokkae",en:"shoulder",pos:"noun"},sentence:{ko:"오래 앉아 있어서 어깨가 아파요.",en:"I sat for a long time so my shoulder hurts."},target:"어깨",options:["body","shoulder","head; also hair"],note:""},{kind:"guess",word:{ko:"팔",romanization:"pal",en:"arm",pos:"noun"},sentence:{ko:"무거운 가방을 들어서 팔이 아파요.",en:"I carried a heavy bag so my arm hurts."},target:"팔",options:["body","arm","head; also hair"],note:""},{kind:"guess",word:{ko:"손",romanization:"son",en:"hand",pos:"noun"},sentence:{ko:"손을 씻어요.",en:"I wash my hands."},target:"손",options:["body","head; also hair","hand"],note:""},{kind:"guess",word:{ko:"손가락",romanization:"songarak",en:"finger",pos:"noun"},sentence:{ko:"문에 손가락이 끼어서 아파요.",en:"My finger got caught in the door so it hurts."},target:"손가락",options:["finger","body","head; also hair"],note:""},{kind:"guess",word:{ko:"배",romanization:"bae",en:"belly; stomach",pos:"noun",nuance:"배 means the belly/stomach (the body region), and the same syllable also means 'pear' and 'boat/ship' — three homonyms split only by context. Hunger and fullness are locked set phrases that ALWAYS keep 배: 배가 고프다 (hungry) and 배가 부르다 (full); you cannot say 나는 고파요 alone, which is the top beginner error. Both adjectives are irregular: 고프다 is ㅡ-irregular (고파요, 고팠어요) and 부르다 is 르-irregular (불러요, 불렀어요). Note 배 here is the colloquial stomach for aches and hunger, distinct from the Sino-Korean 위 (胃, the actual stomach organ) used in medical contexts like 위염 (gastritis). A culturally important idiom: 배가 아프다 also figuratively means to be jealous of someone's good fortune ('my stomach hurts' = green with envy), so context decides literal pain vs. envy."},sentence:{ko:"배가 아파요.",en:"My stomach hurts."},target:"배",options:["belly; stomach","body","head; also hair"],note:""},{kind:"guess",word:{ko:"다리",romanization:"dari",en:"leg",pos:"noun"},sentence:{ko:"다리가 아파요.",en:"My leg hurts."},target:"다리",options:["body","head; also hair","leg"],note:""},{kind:"guess",word:{ko:"무릎",romanization:"mureup",en:"knee",pos:"noun"},sentence:{ko:"계단을 많이 올라서 무릎이 아파요.",en:"I climbed a lot of stairs so my knee hurts."},target:"무릎",options:["knee","body","head; also hair"],note:""},{kind:"guess",word:{ko:"발",romanization:"bal",en:"foot",pos:"noun"},sentence:{ko:"발이 아파요.",en:"My foot hurts."},target:"발",options:["body","head; also hair","foot"],note:""}]},{id:"snack-time",packId:"pack-time",kind:"snack",title:"Time And Days",shortTitle:"Time",afterChapter:5,level:"A1",canDo:"Understand today, tomorrow, weekdays, and simple appointment timing.",index:0,cardCount:18,cards:[{kind:"guess",word:{ko:"오늘",romanization:"oneul",en:"today",pos:"noun",nuance:"오늘 usually does not need 에. 오늘에 sounds unnatural for ordinary “today.”"},sentence:{ko:"오늘은 학교에 가요.",en:"Today, I go to school."},target:"오늘",options:["yesterday","today","tomorrow"],note:""},{kind:"guess",word:{ko:"어제",romanization:"eoje",en:"yesterday",pos:"noun",nuance:"어제 is a native deictic time word meaning 'yesterday', sitting in the set 그저께(엊그제) 'day before yesterday' – 어제 – 오늘 'today' – 내일 'tomorrow' – 모레 'day after tomorrow'. Its defining grammar quirk is that, like 오늘 and 내일, it normally takes NO 에: you say 어제 만났어요, never 어제에. (The particle reappears only when 어제 combines with a sub-period, e.g. 어제 아침에, where 에 attaches to 아침.) 어제 naturally pairs with past tense — 았어요/었어요 — so it's a reliable signal that the verb should be past. Habitual partners: 어제 아침/저녁, 어제부터, 어제 일 'yesterday's matter', 어제 본/한/간 + noun. The big English-speaker pitfall is over-marking with 에 by analogy to 'on' or to other time nouns like 주말에; bare 어제 is correct. A second trap is pairing 어제 with present or future tense; because it's firmly past, 어제 가요 is wrong — it must be 어제 갔어요."},sentence:{ko:"어제 친구를 만났어요.",en:"I met a friend yesterday."},target:"어제",options:["today","tomorrow","yesterday"],note:""},{kind:"guess",word:{ko:"내일",romanization:"naeil",en:"tomorrow",pos:"noun",nuance:"내일 is a time word, so it can appear naturally without 에."},sentence:{ko:"내일 봐요.",en:"See you tomorrow."},target:"내일",options:["today","tomorrow","yesterday"],note:""},{kind:"guess",word:{ko:"지금",romanization:"jigeum",en:"now",pos:"adverb",nuance:"지금 usually comes near the beginning of the sentence or before the verb phrase."},sentence:{ko:"지금 가요.",en:"I am going now."},target:"지금",options:["today","yesterday","now"],note:""},{kind:"guess",word:{ko:"아침",romanization:"achim",en:"morning; also breakfast",pos:"noun",nuance:"아침 is a native Korean word that does double duty: the early part of the day (roughly sunrise to mid-morning) and the breakfast meal — the same way English 'morning' differs from the meal but Korean merges the breakfast sense into the time word. The grammar disambiguates: with 에 (아침에) it's the time, with 을 (아침을 먹다) it's the food. Contrast 아침 vs 오전: 아침 is the felt, lived early morning, while 오전 午前 is the neutral clock-AM you put on timetables — so 아침에 일어나요 (waking life) but 오전 9시 회의 (a scheduled item). Habitual partners: 아침에 일어나다/운동하다, 아침을 먹다/거르다 ('skip breakfast'), 아침 일찍, 매일 아침. The big English-speaker pitfall is using 오전 for the breakfast meal — 오전 is only the clock period and can never name food, so 'eat breakfast' must be 아침을 먹다, never 오전을 먹다. Also don't force 에 onto the meal sense: you eat 아침을, you don't 'eat at morning'."},sentence:{ko:"아침에 커피를 마셔요.",en:"I drink coffee in the morning."},target:"아침",options:["today","morning; also breakfast","yesterday"],note:""},{kind:"guess",word:{ko:"점심",romanization:"jeomsim",en:"lunch / noon",pos:"noun"},sentence:{ko:"점심 같이 먹어요.",en:"Let's have lunch together."},target:"점심",options:["today","yesterday","lunch / noon"],note:""},{kind:"guess",word:{ko:"저녁",romanization:"jeonyeok",en:"evening; also dinner",pos:"noun",nuance:"저녁 is a native Korean word covering the early-night period AND the dinner meal, mirroring 아침/점심: 저녁을 먹다 is the food, 저녁에 is the time. The fine line is 저녁 vs 밤: 저녁 is the social early evening — dusk through dinner, when people are still out — whereas 밤 is true late night when it's dark and quiet; so a 7 p.m. dinner is 저녁, but 11 p.m. is 밤. 저녁 also contrasts with the clock label 오후, which ends as 저녁 begins. Habitual partners: 저녁을 먹다, 저녁 식사, 저녁 약속, 저녁 메뉴, 저녁에 만나다. The main English-speaker pitfall is using 밤 for the dinner meal because 'night' feels close — but 'eat dinner' is 저녁을 먹다, never 밤을 먹다 (밤 can't name a meal, and 밤 also happens to mean 'chestnut'). A second trap: don't mark the dinner-meal with 에; you eat 저녁을, while 저녁에 means 'in the evening (do something)'."},sentence:{ko:"저녁에 영화를 봐요.",en:"I watch a movie in the evening."},target:"저녁",options:["today","evening; also dinner","yesterday"],note:""},{kind:"guess",word:{ko:"밤",romanization:"bam",en:"night",pos:"noun"},sentence:{ko:"밤에 책을 읽어요.",en:"I read books at night."},target:"밤",options:["night","today","yesterday"],note:""},{kind:"guess",word:{ko:"주말",romanization:"jumal",en:"weekend",pos:"noun",nuance:"주말 is Sino-Korean, 週末 — 週 'week' + 末 'end', literally 'week-end', and its opposites are 평일 平日 'weekday' and 주중 週中 'midweek'. It refers to Saturday and Sunday as a block. The contrast worth noting is 주말 vs 휴일: 주말 is specifically the weekend, while 휴일 休日 is any day off including public holidays — so a Wednesday holiday is a 휴일 but not a 주말. Habitual partners: 주말에 쉬다/놀다, 이번/지난/다음 주말, 주말마다, 즐거운 주말, and the farewell 주말 잘 보내세요. The English-speaker pitfall is the particle: learners borrow 'at/on' loosely and write 주말에서, but 에서 marks a LOCATION or a source ('from'); the time-when always takes 에 → 주말에. A second subtlety: for 'this weekend' use 이번 주말 (이번 = the current instance), not 오늘 주말; and 다음 주말 'next weekend' vs 다음 주 주말 can differ, so keep 다음 주말 for the upcoming Sat–Sun."},sentence:{ko:"주말에 보통 쉬어요.",en:"I usually rest on the weekend."},target:"주말",options:["weekend","today","yesterday"],note:""},{kind:"guess",word:{ko:"월요일",romanization:"woryoil",en:"Monday",pos:"noun"},sentence:{ko:"오늘은 월요일이에요.",en:"Today is Monday."},target:"월요일",options:["Monday","today","yesterday"],note:""},{kind:"guess",word:{ko:"화요일",romanization:"hwayoil",en:"Tuesday",pos:"noun"},sentence:{ko:"내일은 화요일이에요.",en:"Tomorrow is Tuesday."},target:"화요일",options:["today","Tuesday","yesterday"],note:""},{kind:"guess",word:{ko:"수요일",romanization:"suyoil",en:"Wednesday",pos:"noun"},sentence:{ko:"오늘이 수요일이에요?",en:"Is today Wednesday?"},target:"수요일",options:["Wednesday","today","yesterday"],note:""},{kind:"guess",word:{ko:"목요일",romanization:"mogyoil",en:"Thursday",pos:"noun"},sentence:{ko:"모레가 목요일이에요.",en:"The day after tomorrow is Thursday."},target:"목요일",options:["today","yesterday","Thursday"],note:""},{kind:"guess",word:{ko:"금요일",romanization:"geumyoil",en:"Friday",pos:"noun"},sentence:{ko:"오늘은 금요일이에요.",en:"Today is Friday."},target:"금요일",options:["Friday","today","yesterday"],note:""},{kind:"guess",word:{ko:"토요일",romanization:"toyoil",en:"Saturday",pos:"noun"},sentence:{ko:"내일은 토요일이에요.",en:"Tomorrow is Saturday."},target:"토요일",options:["today","yesterday","Saturday"],note:""},{kind:"guess",word:{ko:"일요일",romanization:"iryoil",en:"Sunday",pos:"noun"},sentence:{ko:"오늘이 일요일이에요?",en:"Is today Sunday?"},target:"일요일",options:["Sunday","today","yesterday"],note:""},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"시간이 있어요?",en:"Do you have time?"},target:"시간",options:["time","today","yesterday"],note:""},{kind:"guess",word:{ko:"분",romanization:"bun",en:"minute",pos:"noun",nuance:"분 is the time unit 'minute', written with the hanja 分 (to divide/a part) — a minute being a division of the hour. The crucial rule: 분 ALWAYS takes Sino-Korean numbers (일·이·삼·사·오·...), so it's 오 분, 삼십 분, never the native 하나·둘·셋. This creates Korea's famous mixed clock, where the HOUR uses native numbers + 시 (한 시, 두 시) but the MINUTE uses Sino numbers + 분 (십 분, 삼십 분): 한 시 십 분 = 1:10. Note 분 also means 'a respected person' (한 분 = one person, honorific) and is the honorific counter for people — same syllable, totally different word, disambiguated by context. The English-speaker pitfall: applying the native numbers used for 시 to 분 as well (✗한 분 for one minute — that actually means 'one person, honorific'); the correct 'one minute' is 일 분. Collocates with 후/전 (after/before), 동안 (for), 정도 (about), 만 (only), and 걸리다 (to take)."},sentence:{ko:"십 분 남았어요.",en:"Ten minutes are left."},target:"분",options:["today","minute","yesterday"],note:""}]},{id:"snack-people-places",packId:"pack-people-places",kind:"snack",title:"People And Places",shortTitle:"People + Places",afterChapter:4,level:"A1",canDo:"Recognize the people and places that appear in first conversations and errands.",index:0,cardCount:16,cards:[{kind:"guess",word:{ko:"한국",romanization:"hanguk",en:"Korea",pos:"noun"},sentence:{ko:"저는 한국 사람이에요.",en:"I am Korean."},target:"한국",options:["USA","Korea","China"],note:""},{kind:"guess",word:{ko:"미국",romanization:"miguk",en:"USA",pos:"noun"},sentence:{ko:"저는 미국에서 왔어요.",en:"I came from the USA."},target:"미국",options:["Korea","China","USA"],note:""},{kind:"guess",word:{ko:"중국",romanization:"jungguk",en:"China",pos:"noun"},sentence:{ko:"저는 중국에서 왔어요.",en:"I came from China."},target:"중국",options:["Korea","China","USA"],note:""},{kind:"guess",word:{ko:"일본",romanization:"ilbon",en:"Japan",pos:"noun"},sentence:{ko:"저는 일본 사람이에요.",en:"I am Japanese."},target:"일본",options:["Korea","Japan","USA"],note:""},{kind:"guess",word:{ko:"사람",romanization:"saram",en:"person / people",pos:"noun",nuance:"사람 can mean one person or people in general. It is useful for describing crowds, identity, and who someone is."},sentence:{ko:"사람이 많아요.",en:"There are many people."},target:"사람",options:["Korea","USA","person / people"],note:""},{kind:"guess",word:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",nuance:"친구 can mean friend or same-age peer depending on context."},sentence:{ko:"제 친구예요.",en:"This is my friend."},target:"친구",options:["Korea","USA","friend"],note:""},{kind:"guess",word:{ko:"학생",romanization:"haksaeng",en:"student",pos:"noun",nuance:"학생 is a common identity word. Use 이에요 after 학생 because it ends in a consonant."},sentence:{ko:"저는 학생이에요.",en:"I am a student."},target:"학생",options:["student","Korea","USA"],note:""},{kind:"guess",word:{ko:"선생님",romanization:"seonsaengnim",en:"teacher",pos:"noun",nuance:"님 makes the word respectful. 선생님 is also used as a polite title."},sentence:{ko:"우리 선생님이에요.",en:"This is our teacher."},target:"선생님",options:["Korea","teacher","USA"],note:""},{kind:"guess",word:{ko:"의사",romanization:"uisa",en:"doctor",pos:"noun",nuance:"의사 is Sino-Korean 醫師 ('medicine' 醫 + 'master/teacher' 師), so the word literally frames a doctor as a master of medicine — which is why Koreans almost reflexively append 선생님 (의사 선생님) when addressing or referring to one, the way English keeps 'Doctor' as a title. Saying bare 의사 to or about a specific physician can sound flat or even slightly disrespectful, like calling them 'the doc'. Distinguish 의사 (the licensed physician) from 의자 'chair', which differs by a single vowel and trips up beginners constantly, and from 환자 'patient' and 간호사 'nurse', the other people in the room. The natural verb is 환자를 보다 ('see patients') or 진료를 보다/받다, never the English-style '의사를 하다'; a doctor 의사가 되다 ('becomes' a doctor), with the goal marked by 가, not 을."},sentence:{ko:"저는 의사예요.",en:"I am a doctor."},target:"의사",options:["Korea","USA","doctor"],note:""},{kind:"guess",word:{ko:"회사원",romanization:"hoesawon",en:"office worker",pos:"noun",nuance:"회사원 is 會社員 ('company-member'), literally a member of a company, and it is the neutral catch-all a salaried employee of a private firm gives when asked 무슨 일 하세요? Contrast it with 직장인, which means 'a working person' in general (anyone with a paid job, including teachers or nurses): every 회사원 is a 직장인, but not every 직장인 is a 회사원. Also separate it from 사업가, the owner who runs the business — a 회사원 is employed by someone else. The pitfall for English speakers is twofold: 회사원 ends in a consonant so the copula is 회사원이에요, never 'office worker'-style 회사원예요; and don't translate 'I work at a company' as a job title — to name the job you simply say 회사원이에요 rather than literally rendering the English sentence."},sentence:{ko:"저는 회사원이에요.",en:"I'm an office worker."},target:"회사원",options:["Korea","office worker","USA"],note:""},{kind:"guess",word:{ko:"학교",romanization:"hakgyo",en:"school",pos:"noun",nuance:"학교 is one of the clearest words for practicing 에 vs 에서."},sentence:{ko:"학교에 가요.",en:"I go to school."},target:"학교",options:["Korea","USA","school"],note:""},{kind:"guess",word:{ko:"회사",romanization:"hoesa",en:"company / workplace",pos:"noun",nuance:"회사 often means workplace in daily conversation, not only the company as an organization."},sentence:{ko:"회사에 가요.",en:"I go to work."},target:"회사",options:["company / workplace","Korea","USA"],note:""},{kind:"guess",word:{ko:"병원",romanization:"byeongwon",en:"hospital / clinic",pos:"noun",nuance:"병원 can mean hospital or clinic in everyday Korean."},sentence:{ko:"아파서 병원에 가요.",en:"I am sick, so I go to the hospital."},target:"병원",options:["Korea","hospital / clinic","USA"],note:""},{kind:"guess",word:{ko:"식당",romanization:"sikdang",en:"restaurant; eatery; cafeteria",pos:"noun",nuance:"식당 is 食堂 — 食 'eat' + 堂 'hall' — an 'eating hall', i.e. an ordinary, everyday place to have a meal: a neighborhood eatery, a noodle shop, or a 구내식당(cafeteria). The register contrast is 레스토랑, the loanword reserved for fancier, often Western, sit-down dining; you'd call a humble 백반집 a 식당, never a 레스토랑, and a candlelit Italian place a 레스토랑, not a plain 식당. The crucial grammar point is particle choice: use 에서 for an action done there (식당에서 먹어요 'eat AT the restaurant') but 에 for it as a destination (식당에 가요 'go TO the restaurant'). The English-speaker pitfall is exactly this 에/에서 split, since English 'at/to' don't map one-to-one; another is reaching for 레스토랑 as the default word for any restaurant when 식당 is the everyday term."},sentence:{ko:"우리 이 식당에서 점심 먹어요.",en:"Let's eat lunch at this restaurant."},target:"식당",options:["Korea","restaurant; eatery; cafeteria","USA"],note:""},{kind:"guess",word:{ko:"카페",romanization:"kape",en:"cafe",pos:"noun",nuance:"카페 is a loanword (from French/English 'café') meaning a coffee shop — but in Korea it is as much a social and study space as a place to drink coffee; people sit for hours to chat, work on laptops, or go on a 카페 투어 of photogenic spots. The key contrast learners blur is 카페 vs 커피: 카페 is the *place*, 커피 is the *drink*, so '커피 마시러 카페에 가요' (go to the cafe to drink coffee). It overlaps with 커피숍 and the older 다방 (a dated tea-room), but 카페 is the modern default. Being borrowed, it has no hanja. The English-speaker pitfall is exactly that 카페/커피 mix-up, plus the particles — 카페에 가요 for going there but 카페에서 공부해요 for doing something there — and remember the purpose marker for 'to go drink coffee' is the verb stem + ~(으)러: 커피 마시러 카페에 가요."},sentence:{ko:"카페가 예뻐요.",en:"The cafe is pretty."},target:"카페",options:["cafe","Korea","USA"],note:""},{kind:"guess",word:{ko:"화장실",romanization:"hwajangsil",en:"bathroom / restroom",pos:"noun",nuance:"화장실 is the normal public word for bathroom/restroom."},sentence:{ko:"화장실 어디예요?",en:"Where is the bathroom?"},target:"화장실",options:["Korea","bathroom / restroom","USA"],note:""}]},{id:"snack-home-things",packId:"pack-home-things",kind:"snack",title:"Home And Things",shortTitle:"Home Things",afterChapter:6,level:"A1",canDo:"Talk about your room, belongings, and everyday objects around you.",index:0,cardCount:16,cards:[{kind:"guess",word:{ko:"집",romanization:"jip",en:"home / house",pos:"noun",nuance:"집 can mean home or house. 집에 often means “home” in movement/location sentences."},sentence:{ko:"집에 가요.",en:"I go home."},target:"집",options:["room","home / house","door"],note:""},{kind:"guess",word:{ko:"방",romanization:"bang",en:"room",pos:"noun",nuance:"방 is the Sino-Korean character 房 ('room, chamber') and is the all-purpose word for any enclosed room, and it builds dozens of everyday compounds: 안방 (master/main room), 공부방 (study room), 노래방 (singing room/karaoke), 찜질방 (Korean sauna room), and PC방 (internet cafe). The key contrast to fix in your head is 방 vs 집: 집 is the whole house/home, but 방 is just one room inside it, so 'I'm going home' must be 집에 가요, never 방에 가요. The grammar trap is the 에 vs 에서 split: merely being located in the room uses 에 (방에 있어요 = it's in the room), but any action carried out inside the room uses 에서 (방에서 공부해요 = I study in my room) — English 'in the room' blurs both, and overusing 에 for actions is the #1 beginner error. Collocations: 방을 치우다/정리하다 (tidy the room), 방이 좁다 (the room is cramped). Register is fully neutral, used by everyone."},sentence:{ko:"여기가 제 방이에요.",en:"This is my room."},target:"방",options:["home / house","door","room"],note:""},{kind:"guess",word:{ko:"문",romanization:"mun",en:"door",pos:"noun"},sentence:{ko:"문 좀 닫아 주세요.",en:"Please close the door."},target:"문",options:["home / house","room","door"],note:""},{kind:"guess",word:{ko:"창문",romanization:"changmun",en:"window",pos:"noun"},sentence:{ko:"창문 좀 열어도 돼요?",en:"May I open the window?"},target:"창문",options:["home / house","room","window"],note:""},{kind:"guess",word:{ko:"책상",romanization:"chaeksang",en:"desk",pos:"noun"},sentence:{ko:"책상 위에 노트북이 있어요.",en:"There's a laptop on the desk."},target:"책상",options:["desk","home / house","room"],note:""},{kind:"guess",word:{ko:"의자",romanization:"uija",en:"chair",pos:"noun",nuance:"의자 is Sino-Korean 椅子 ('chair') and covers any seat with legs — dining chairs, office chairs (사무용 의자 or 사무 의자), folding chairs (접이식 의자). The single most common English-speaker error is the particle with 앉다: sitting DOWN is reaching a resting position, so it must be 의자에 앉아요 (에 = destination), not 의자에서 앉아요 — even though English 'sit ON the chair' tempts you toward a location particle. Compare with standing up, which is motion away and DOES take 에서: 의자에서 일어나요. Distinguish 의자 (chair, you sit on it) from 소파 (sofa/couch, plush multi-seat) and 책상 (desk) — beginners sometimes pair them loosely. The set phrase for offering someone a seat is 의자를 빼 드리다 (pull the chair out for them). Register is neutral."},sentence:{ko:"여기 의자에 앉으세요.",en:"Please have a seat on this chair."},target:"의자",options:["home / house","chair","room"],note:""},{kind:"guess",word:{ko:"침대",romanization:"chimdae",en:"bed",pos:"noun"},sentence:{ko:"저는 침대에서 안 자고 바닥에서 자요.",en:"I don't sleep in a bed, I sleep on the floor."},target:"침대",options:["home / house","room","bed"],note:""},{kind:"guess",word:{ko:"옷",romanization:"ot",en:"clothes",pos:"noun",nuance:"옷 is a pure native Korean word (no hanja) meaning clothes/clothing for the body, and the verb you MUST pair it with is 입다 (to wear on the torso/body) — never 신다, which is reserved for footwear on the feet (신발을 신다), nor 쓰다 (hats/glasses) nor 끼다 (gloves/rings). English 'wear/put on' covers every garment with one verb, so this split is the central pitfall: 옷을 신어요 is a classic beginner error. To take clothes off is 벗다, to change them 갈아입다. For 'these clothes look good on you,' Korean says 옷이 잘 어울려요 (the clothes suit you), not a direct translation of 'you look good.' Note 옷 is treated as singular/uncountable grammatically (no plural needed): one outfit or a wardrobe full is still just 옷. The dressier counterpart 의상 (costume/attire, 衣裳) is for performances or formal contexts. Register is neutral and everyday."},sentence:{ko:"오늘 뭐 입을까요?",en:"What should I wear today?"},target:null,options:["home / house","room","clothes"],note:""},{kind:"guess",word:{ko:"신발",romanization:"sinbal",en:"shoes",pos:"noun"},sentence:{ko:"들어올 때 신발 벗어 주세요.",en:"Please take your shoes off when you come in."},target:"신발",options:["home / house","shoes","room"],note:""},{kind:"guess",word:{ko:"가방",romanization:"gabang",en:"bag",pos:"noun"},sentence:{ko:"책을 가방에 넣었어요.",en:"I put the book into the bag."},target:"가방",options:["home / house","room","bag"],note:""},{kind:"guess",word:{ko:"책",romanization:"chaek",en:"book",pos:"noun",nuance:"책 is useful with 읽다, 사다, 있다, and 없다. It also helps beginners practice object marker 을 because 책 ends in a consonant."},sentence:{ko:"책을 읽어요.",en:"I read a book."},target:"책",options:["home / house","room","book"],note:""},{kind:"guess",word:{ko:"펜",romanization:"pen",en:"pen",pos:"noun"},sentence:{ko:"펜으로 이름을 써요.",en:"I write my name with a pen."},target:"펜",options:["home / house","pen","room"],note:""},{kind:"guess",word:{ko:"휴대폰",romanization:"hyudaepon",en:"cellphone",pos:"noun"},sentence:{ko:"휴대폰 배터리가 다 됐어요.",en:"My phone battery is dead."},target:"휴대폰",options:["cellphone","home / house","room"],note:""},{kind:"guess",word:{ko:"컴퓨터",romanization:"keompyuteo",en:"computer",pos:"noun"},sentence:{ko:"잠깐만요, 컴퓨터 좀 켤게요.",en:"One moment, let me turn on the computer."},target:"컴퓨터",options:["home / house","room","computer"],note:""},{kind:"guess",word:{ko:"우산",romanization:"usan",en:"umbrella",pos:"noun",nuance:"우산 is Sino-Korean 雨傘, literally 雨 'rain' + 傘 'umbrella/parasol' — so the word transparently means 'rain-umbrella', which is your built-in reminder it's for rain. The verb is the deceptively busy 쓰다: to put up/use an umbrella is 우산을 쓰다, the same 쓰다 that covers wearing a hat (모자를 쓰다) and glasses (안경을 쓰다) — Korean groups 'things over your head/face' under 쓰다, distinct from 입다 (clothes on the torso/legs) and 신다 (footwear). The contrast to file away is 우산 vs 양산: both are 傘, but 우산 (雨傘) is the rain umbrella while 양산 (陽傘, 'sun-shade') is a parasol against sunlight — different words for different weather. Useful collocations: 우산을 쓰다/접다/펴다 (put up / fold / open an umbrella), 우산을 챙기다 (remember to grab an umbrella), 우산을 깜빡하다 (forget the umbrella). A folding umbrella is 접는 우산 or 3단 우산, a long one 장우산. Pitfall: English 'wear/carry an umbrella' must become 쓰다 (use over the head), never 입다, and don't reuse 우산 for a sun parasol — that's 양산."},sentence:{ko:"비가 와요. 우산 있어요?",en:"It's raining. Do you have an umbrella?"},target:"우산",options:["home / house","umbrella","room"],note:""},{kind:"guess",word:{ko:"돈",romanization:"don",en:"money",pos:"noun",nuance:"돈 is money. In stores, 카드 and 현금 are often more specific and useful."},sentence:{ko:"돈이 있어요.",en:"I have money."},target:"돈",options:["money","home / house","room"],note:""}]},{id:"snack-food-basic",packId:"pack-food-basic",kind:"snack",title:"Food Basics",shortTitle:"Food",afterChapter:7,level:"A1",canDo:"Read menus and say simple food preferences or restrictions.",index:0,cardCount:16,cards:[{kind:"guess",word:{ko:"밥",romanization:"bap",en:"cooked rice; a meal",pos:"noun",nuance:"밥 literally is the bowl of cooked white rice, but by extension it is the default word for 'a meal' — which is why 밥 먹었어요? functions as a real greeting like 'how are you?', not a literal question about rice. Contrast it with 식사(食事), the polite Sino-Korean word for 'a meal': you offer an elder 식사하셨어요?, never the blunt 밥 먹었어요?. The verb is 먹다(eat), and to cook rice you say 밥을 하다 or 밥을 짓다, not 밥을 만들다. The big English-speaker pitfall is hearing 밥 only as 'rice' and missing that 밥 먹자 means 'let's grab a bite', and that to a boss you must upgrade to 식사 to stay polite."},sentence:{ko:"저는 아침에 밥을 먹어요.",en:"I eat rice in the morning."},target:"밥",options:["water","kimchi (fermented vegetable side dish)","cooked rice; a meal"],note:""},{kind:"guess",word:{ko:"물",romanization:"mul",en:"water",pos:"noun",nuance:"물 is essential in restaurants. 물 주세요 is more useful than just knowing “water.”"},sentence:{ko:"물 주세요.",en:"Water, please."},target:"물",options:["water","cooked rice; a meal","kimchi (fermented vegetable side dish)"],note:""},{kind:"guess",word:{ko:"김치",romanization:"gimchi",en:"kimchi (fermented vegetable side dish)",pos:"noun"},sentence:{ko:"저는 김치를 정말 좋아해요.",en:"I really like kimchi."},target:"김치",options:["cooked rice; a meal","kimchi (fermented vegetable side dish)","water"],note:""},{kind:"guess",word:{ko:"고기",romanization:"gogi",en:"meat (esp. pork or beef)",pos:"noun",nuance:"In everyday speech 고기 by default means red land meat — usually 돼지고기(pork) or 소고기(beef) — so 고기 먹으러 가자 implies a BBQ, not seafood. To be specific you compound the animal onto 고기: 닭고기(chicken), 소고기(beef), 돼지고기(pork). The words to contrast are 생선(fish as food) and 해산물(seafood), which Koreans do NOT file under 고기; chicken sits on the edge, so people usually say 닭고기 rather than bare 고기 for it. The set cooking verb is 굽다, a ㅂ-irregular that becomes 구워요/구웠어요 (not 'gubeoyo'). The English-speaker pitfall is the English umbrella sense of 'meat' that includes fish and poultry — in Korean, unmarked 고기 leans strongly toward pork/beef, and you should name the animal when you mean otherwise."},sentence:{ko:"오늘 저녁에 고기 먹고 싶어요.",en:"I want to eat meat tonight."},target:"고기",options:["cooked rice; a meal","water","meat (esp. pork or beef)"],note:""},{kind:"guess",word:{ko:"생선",romanization:"saengseon",en:"fish (as food)",pos:"noun"},sentence:{ko:"저는 생선을 자주 먹어요.",en:"I eat fish often."},target:"생선",options:["cooked rice; a meal","fish (as food)","water"],note:""},{kind:"guess",word:{ko:"야채",romanization:"yachae",en:"vegetables",pos:"noun"},sentence:{ko:"저는 야채를 많이 먹어요.",en:"I eat a lot of vegetables."},target:"야채",options:["vegetables","cooked rice; a meal","water"],note:""},{kind:"guess",word:{ko:"과일",romanization:"gwail",en:"fruit",pos:"noun"},sentence:{ko:"저는 과일을 매일 먹어요.",en:"I eat fruit every day."},target:"과일",options:["cooked rice; a meal","fruit","water"],note:""},{kind:"guess",word:{ko:"빵",romanization:"ppang",en:"bread (and baked goods generally)",pos:"noun"},sentence:{ko:"저는 아침에 빵을 먹어요.",en:"I eat bread in the morning."},target:"빵",options:["cooked rice; a meal","bread (and baked goods generally)","water"],note:""},{kind:"guess",word:{ko:"우유",romanization:"uyu",en:"milk (cow's milk)",pos:"noun"},sentence:{ko:"저는 매일 우유를 마셔요.",en:"I drink milk every day."},target:"우유",options:["cooked rice; a meal","milk (cow's milk)","water"],note:""},{kind:"guess",word:{ko:"계란",romanization:"gyeran",en:"egg",pos:"noun"},sentence:{ko:"계란 한 판에 얼마예요?",en:"How much is a tray of eggs?"},target:"계란",options:["cooked rice; a meal","water","egg"],note:""},{kind:"guess",word:{ko:"커피",romanization:"keopi",en:"coffee",pos:"noun",nuance:"In speech, 커피 마셔요 without 를 is also natural, but learn the full frame first."},sentence:{ko:"커피 주세요.",en:"Coffee, please."},target:"커피",options:["cooked rice; a meal","water","coffee"],note:""},{kind:"guess",word:{ko:"차",romanization:"cha",en:"tea",pos:"noun",nuance:"차 (茶) is the Sino-Korean word for 'tea,' the brewed leaf or herbal drink, and because it is a beverage it must pair with 마시다 (to drink), never 먹다 (to eat) — though casual speakers do say 차를 먹다 colloquially, learners should default to 마시다. The same syllable 차 (車) also means 'car/vehicle,' so only context separates 차를 마시다 (drink tea) from 차를 타다 (ride a car); they are written identically. Unlike English 'tea,' Korean 차 covers herbal and grain infusions too, so 보리차 (barley tea) and 옥수수차 (corn tea) are 차 even with no tea leaves. A common English-speaker pitfall is reaching for 먹다 by analogy with 'have some tea,' but in standard Korean a polite host says 차 드세요 (드시다 being the honorific of 마시다/먹다). Natural collocations include 차를 우리다 (steep tea) and 차 한 잔 하다 (literally 'do one cup of tea,' meaning to chat over tea)."},sentence:{ko:"저는 아침에 차를 마셔요.",en:"I drink tea in the morning."},target:"차",options:["cooked rice; a meal","tea","water"],note:""},{kind:"guess",word:{ko:"맥주",romanization:"maekju",en:"beer",pos:"noun"},sentence:{ko:"맥주 한 잔 어때요?",en:"How about a glass of beer?"},target:"맥주",options:["beer","cooked rice; a meal","water"],note:""},{kind:"guess",word:{ko:"소주",romanization:"soju",en:"soju",pos:"noun"},sentence:{ko:"소주 한 병 주세요.",en:"One bottle of soju, please."},target:"소주",options:["soju","cooked rice; a meal","water"],note:""},{kind:"guess",word:{ko:"음식",romanization:"eumsik",en:"food",pos:"noun",nuance:"음식 is the general word for food or cuisine. It combines naturally with Korean, spicy, delicious, and eat."},sentence:{ko:"한국 음식을 먹고 싶어요.",en:"I want to eat Korean food."},target:"음식",options:["food","cooked rice; a meal","water"],note:""},{kind:"guess",word:{ko:"음료수",romanization:"eumnyosu",en:"beverage",pos:"noun"},sentence:{ko:"뭐 마실래요? 음료수 드릴까요?",en:"What would you like to drink? Shall I get you a drink?"},target:"음료수",options:["cooked rice; a meal","water","beverage"],note:""}]},{id:"snack-colors",packId:"pack-colors",kind:"snack",title:"Color Words",shortTitle:"Colors",afterChapter:16,level:"A2",canDo:"Describe objects by color in shopping, clothing, and everyday descriptions.",index:0,cardCount:12,cards:[{kind:"guess",word:{ko:"빨간색",romanization:"ppalgansaek",en:"red",pos:"noun"},sentence:{ko:"이 사과는 빨간색이에요.",en:"This apple is red."},target:"빨간색",options:["red","blue","yellow"],note:""},{kind:"guess",word:{ko:"파란색",romanization:"paransaek",en:"blue",pos:"noun"},sentence:{ko:"하늘이 파란색이에요.",en:"The sky is blue."},target:"파란색",options:["red","blue","yellow"],note:""},{kind:"guess",word:{ko:"노란색",romanization:"noransaek",en:"yellow",pos:"noun"},sentence:{ko:"이 꽃은 노란색이에요.",en:"This flower is yellow."},target:"노란색",options:["yellow","red","blue"],note:""},{kind:"guess",word:{ko:"초록색",romanization:"choroksaek",en:"green",pos:"noun"},sentence:{ko:"저는 초록색을 좋아해요.",en:"I like green."},target:"초록색",options:["red","blue","green"],note:""},{kind:"guess",word:{ko:"검은색",romanization:"geomeunsaek",en:"black",pos:"noun"},sentence:{ko:"이 가방은 검은색이에요.",en:"This bag is black."},target:"검은색",options:["red","blue","black"],note:""},{kind:"guess",word:{ko:"하얀색",romanization:"hayansaek",en:"white",pos:"noun"},sentence:{ko:"겨울에 눈이 와서 세상이 하얀색이에요.",en:"It snowed in winter so the world is white."},target:"하얀색",options:["red","blue","white"],note:""},{kind:"guess",word:{ko:"갈색",romanization:"galsaek",en:"brown",pos:"noun"},sentence:{ko:"머리를 갈색으로 염색했어요.",en:"I dyed my hair brown."},target:"갈색",options:["red","brown","blue"],note:""},{kind:"guess",word:{ko:"회색",romanization:"hoesaek",en:"gray",pos:"noun"},sentence:{ko:"오늘 하늘이 회색이라 비 올 것 같아요.",en:"The sky is gray today, so it looks like it'll rain."},target:"회색",options:["gray","red","blue"],note:""},{kind:"guess",word:{ko:"분홍색",romanization:"bunhongsaek",en:"pink",pos:"noun"},sentence:{ko:"벚꽃이 분홍색이라서 진짜 예뻐요.",en:"The cherry blossoms are pink, so they're really pretty."},target:"분홍색",options:["red","pink","blue"],note:""},{kind:"guess",word:{ko:"보라색",romanization:"borasaek",en:"purple",pos:"noun"},sentence:{ko:"저는 보라색을 제일 좋아해요.",en:"Purple is my favorite color."},target:"보라색",options:["purple","red","blue"],note:""},{kind:"guess",word:{ko:"주황색",romanization:"juhwangsaek",en:"orange (color)",pos:"noun"},sentence:{ko:"주황색 우산이 눈에 잘 띄어요.",en:"The orange umbrella stands out well."},target:"주황색",options:["red","blue","orange (color)"],note:""},{kind:"guess",word:{ko:"색깔",romanization:"saekkkal",en:"color",pos:"noun",nuance:"색깔 is the everyday, standalone word for 'color,' built on the Sino-Korean root 색 (色 'color') plus a native suffix that makes it feel fuller and more conversational. Its near-synonym is just 색: the dividing line is grammatical, not meaning — 색깔 stands on its own (색깔이 예뻐요, 무슨 색깔?), while 색 is the building block that fuses to a specific shade name (파란색 blue, 빨간색 red, 노란색 yellow). A more formal, technical synonym is 색상, common in design and shopping ('color option'). The main English-speaker pitfall is over-using 색깔 by sticking it onto shade names — '파란색깔' is wrong; the named colors take 색, giving 파란색. Also, to ask 'what color,' the natural question word is 무슨 색깔, not 어떤 색깔 (which leans toward 'what kind/sort of color')."},sentence:{ko:"무슨 색깔이에요?",en:"What color is it?"},target:"색깔",options:["red","color","blue"],note:""}]},{id:"snack-reactions-agree",packId:"pack-reactions-agree",kind:"snack",title:"Agreeing & Understanding",shortTitle:"Agree",afterChapter:2,level:"A1",canDo:"Show you're listening — half of a real conversation is reacting, not producing new sentences.",index:0,cardCount:10,cards:[{kind:"guess",word:{ko:"맞아요",romanization:"majayo",en:"That's right / You're right.",pos:"expression"},sentence:{ko:"A: 이 길로 가면 돼요? / B: 네, 맞아요.",en:"A: Do we go this way? / B: Yes, that's right."},target:"맞아요",options:["I understand / okay.","That's right / You're right."],note:""},{kind:"guess",word:{ko:"그러게요",romanization:"geureogeyo",en:"Right? / exactly / I know, right — agreeing that you feel the same, often a bit helplessly.",pos:"expression"},sentence:{ko:"A: 오늘 진짜 덥다 / B: 그러게.",en:"A: It's really hot today / B: Right?"},target:null,options:["I understand / okay.","Right? / exactly / I know, right — agreeing that you feel the same, often a bit helplessly."],note:""},{kind:"guess",word:{ko:"그러니까요",romanization:"geureonikkayo",en:"Exactly / that's what I'm saying — emphatic agreement with someone's opinion or complaint.",pos:"expression"},sentence:{ko:"A: 요즘 배달비가 너무 비싸요 / B: 그러니까요. 음식값보다 더 나올 때도 있어요.",en:"A: Delivery fees are so expensive these days / B: Exactly. Sometimes it comes out higher than the food."},target:"그러니까요",options:["I understand / okay.","Exactly / that's what I'm saying — emphatic agreement with someone's opinion or complaint."],note:""},{kind:"guess",word:{ko:"그렇군요",romanization:"geureokunyo",en:"I see / so that's how it is — calmly taking in information you've just been told.",pos:"expression"},sentence:{ko:"A: 이 건물은 주말엔 문을 닫아요 / B: 아, 그렇군요. 몰랐어요.",en:"A: This building closes on weekends / B: Ah, I see. I didn't know."},target:"그렇군요",options:["I understand / okay.","I see / so that's how it is — calmly taking in information you've just been told."],note:""},{kind:"guess",word:{ko:"저도요",romanization:"jeodoyo",en:"Me too / same here — saying that what they just said about themselves is true of you as well.",pos:"expression"},sentence:{ko:"A: 만나서 반가워요 / B: 저도요.",en:"A: Nice to meet you / B: You too."},target:"저도요",options:["Me too / same here — saying that what they just said about themselves is true of you as well.","I understand / okay."],note:""},{kind:"guess",word:{ko:"그런 것 같아요",romanization:"geureon geot gatayo",en:"I think so / It seems that way.",pos:"expression"},sentence:{ko:"오늘 비 올까요? — 그런 것 같아요. 아침부터 하늘이 어두웠거든요.",en:"Will it rain today? — Seems like it. The sky has been dark since morning."},target:"그런 것 같아요",options:["I understand / okay.","I think so / It seems that way."],note:""},{kind:"guess",word:{ko:"다행이네요",romanization:"dahaengineyo",en:"Oh good / What a relief / I'm glad to hear that (relieved that things turned out okay)",pos:"expression"},sentence:{ko:"A: 시험 통과했어요. B: 아, 다행이네요.",en:"A: I passed the exam. B: Oh, what a relief."},target:"다행이네요",options:["Oh good / What a relief / I'm glad to hear that (relieved that things turned out okay)"],note:""},{kind:"guess",word:{ko:"잘됐네요",romanization:"jaldwaenneyo",en:"Oh good, that worked out — reacting on the spot to a situation turning out well.",pos:"expression"},sentence:{ko:"A: 다음 주에 재택근무 해도 된대요 / B: 잘됐네요! 출퇴근 시간 아끼겠어요.",en:"A: They said I can work from home next week / B: Oh, that's great! You'll save the commute."},target:"잘됐네요",options:["Oh good, that worked out — reacting on the spot to a situation turning out well.","I understand / okay."],note:""},{kind:"guess",word:{ko:"그렇죠",romanization:"geureochyo",en:"That's right, isn't it / Exactly.",pos:"expression"},sentence:{ko:"요즘 진짜 피곤하죠? — 그렇죠, 요즘 일이 너무 많아요.",en:"It's really exhausting lately, right? — Exactly, there's just too much work."},target:"그렇죠",options:["That's right, isn't it / Exactly.","I understand / okay."],note:""},{kind:"guess",word:{ko:"알겠어요",romanization:"algesseoyo",en:"I understand / okay.",pos:"expression",nuance:"알겠어요 often means “okay, I got it,” not only intellectual understanding."},sentence:{ko:"알겠어요.",en:"I understand."},target:"알겠어요",options:["I understand / okay.","That's right / You're right.","Right? / exactly / I know, right — agreeing that you feel the same, often a bit helplessly."],note:""}]},{id:"snack-reactions-surprise",packId:"pack-reactions-surprise",kind:"snack",title:"Reacting & Surprise",shortTitle:"React",afterChapter:7,level:"A1",canDo:"React like a person, not a textbook — the difference between a chat that dies and one that keeps going.",index:0,cardCount:10,cards:[{kind:"guess",word:{ko:"진짜요?",romanization:"jinjjayo?",en:"Really?! / for real? — surprised, more colloquial and emotional than 정말요.",pos:"expression"},sentence:{ko:"A: 나 로또 됐어 / B: 진짜?!",en:"A: I won the lottery / B: For real?!"},target:null,options:["Whoa / OMG / no way — a gut reaction of shock, disbelief, or mild dismay.","Awesome! / wow / no way — a big reaction to something amazing, shocking, or extreme.","Really?! / for real? — surprised, more colloquial and emotional than 정말요."],note:""},{kind:"guess",word:{ko:"정말요?",romanization:"jeongmaryo?",en:"Really? — a polite check that you heard right, mild surprise or interest.",pos:"expression"},sentence:{ko:"A: 나 합격했어 / B: 정말?!",en:"A: I passed / B: Really?!"},target:null,options:["Awesome! / wow / no way — a big reaction to something amazing, shocking, or extreme.","Oh no, what do we do","Really? — a polite check that you heard right, mild surprise or interest."],note:""},{kind:"guess",word:{ko:"아 그래요?",romanization:"a geuraeyo?",en:"Oh really? / is that so? — light surprise plus a nudge for the other person to tell you more.",pos:"expression"},sentence:{ko:"A: 저 그 영화 벌써 봤어요 / B: 아 그래요? 어땠어요?",en:"A: I already saw that movie / B: Oh really? How was it?"},target:"아 그래요?",options:["Oh really? / is that so? — light surprise plus a nudge for the other person to tell you more.","Whoa / OMG / no way — a gut reaction of shock, disbelief, or mild dismay.","Awesome! / wow / no way — a big reaction to something amazing, shocking, or extreme."],note:""},{kind:"guess",word:{ko:"헐",romanization:"heol",en:"Whoa / OMG / no way — a gut reaction of shock, disbelief, or mild dismay.",pos:"expression",nuance:"헐 is a pure interjection of shock — the involuntary sound that comes out when something startling, dismaying, or unbelievable hits you. It's hugely common in texting and casual conversation among friends and younger people. Because it's a raw exclamation there is no polite form: there is no 헐요 or 헐이에요; it lives entirely in banmal territory. The dividing line against 대박 is emotional direction: 헐 carries surprise often tinged with 'oh no' or dismay, while 대박 leans toward 'wow, that's enormous' — that's why 헐 어떡해 (shock + worry) is a natural pair but 대박 어떡해 is odd. Also don't confuse 헐 with 헉: 헐 is drawn-out disbelief ('whoa, no way'), while 헉 is a sharp one-syllable gasp of fright or physical surprise. The English-speaker pitfall is using 헐 in a professional or respectful setting — to an elder or boss it sounds childish and rude; in those moments use 어머 for neutral surprise or a full 정말요? 그런 일이. A second pitfall is trying to write 헐요 to be polite — simply switch words."},sentence:{ko:"A: 나 폰 잃어버렸어 / B: 헐.",en:"A: I lost my phone / B: Whoa."},target:"헐",options:["Really?! / for real? — surprised, more colloquial and emotional than 정말요.","Oh really? / is that so? — light surprise plus a nudge for the other person to tell you more.","Whoa / OMG / no way — a gut reaction of shock, disbelief, or mild dismay."],note:""},{kind:"guess",word:{ko:"대박",romanization:"daebak",en:"Awesome! / wow / no way — a big reaction to something amazing, shocking, or extreme.",pos:"expression",nuance:"대박 literally means 'a big hit / jackpot' (대 大 'big' + 박 = jackpot), and as a reaction it explodes out for anything extreme — amazingly good, but also shocking or unbelievably bad. It is youth slang and firmly casual: 대박 alone is banmal among friends; for even a little politeness say 대박이에요, though that still reads as informal in flavor. The variant ladder is 대박 → 대박이다 → 대박이에요 → 완전 대박 (intensified). The dividing line against 헐 is emotional direction: 헐 leans toward shock/dismay ('oh no, whoa'), while 대박 leans toward 'wow, that's enormous' — though both can appear together as 헐 대박. Because it's casual slang, the English-speaker pitfall is using it in formal or hierarchical settings — to a boss or elder, 대박 sounds flippant and disrespectful; use 대단하네요 or 굉장하네요 instead. A second pitfall is assuming it's always positive: Koreans say 대박 at a car crash too, meaning 'unbelievable/shocking.'"},sentence:{ko:"A: 나 승진했어 / B: 대박!",en:"A: I got promoted / B: Awesome!"},target:"대박",options:["Really?! / for real? — surprised, more colloquial and emotional than 정말요.","Really? — a polite check that you heard right, mild surprise or interest.","Awesome! / wow / no way — a big reaction to something amazing, shocking, or extreme."],note:""},{kind:"guess",word:{ko:"설마",romanization:"seolma",en:"surely not; no way",pos:"adverb"},sentence:{ko:"설마 벌써 다 팔렸어요?",en:"No way, is it already sold out?"},target:"설마",options:["Really?! / for real? — surprised, more colloquial and emotional than 정말요.","Really? — a polite check that you heard right, mild surprise or interest.","surely not; no way"],note:""},{kind:"guess",word:{ko:"어머",romanization:"eomeo",en:"Oh my / oh! — a quick gasp of surprise, more neutral and usable than 헐.",pos:"expression"},sentence:{ko:"A: (컵을 떨어뜨림) / B: 어머!",en:"A: (drops a cup) / B: Oh!"},target:"어머",options:["Whoa / OMG / no way — a gut reaction of shock, disbelief, or mild dismay.","Oh my / oh! — a quick gasp of surprise, more neutral and usable than 헐.","Awesome! / wow / no way — a big reaction to something amazing, shocking, or extreme."],note:""},{kind:"guess",word:{ko:"아 맞다",romanization:"a matda",en:"Oh right! — the sound of a forgotten thing suddenly surfacing in your own memory.",pos:"expression"},sentence:{ko:"A: 내일 몇 시에 만나요? / B: 아 맞다, 저 내일 병원 가야 돼요.",en:"A: What time should we meet tomorrow? / B: Oh right — I have to go to the hospital tomorrow."},target:"아 맞다",options:["Really?! / for real? — surprised, more colloquial and emotional than 정말요.","Oh right! — the sound of a forgotten thing suddenly surfacing in your own memory.","Oh really? / is that so? — light surprise plus a nudge for the other person to tell you more."],note:""},{kind:"guess",word:{ko:"말도 안 돼",romanization:"maldo an dwae",en:"No way / that's ridiculous / unbelievable — strong disbelief at something absurd or shocking.",pos:"expression"},sentence:{ko:"A: 그 사람이 1등이래 / B: 말도 안 돼.",en:"A: They say that person came first / B: No way."},target:"말도 안 돼",options:["No way / that's ridiculous / unbelievable — strong disbelief at something absurd or shocking.","Really?! / for real? — surprised, more colloquial and emotional than 정말요.","Oh my / oh! — a quick gasp of surprise, more neutral and usable than 헐."],note:""},{kind:"guess",word:{ko:"어떡해요",romanization:"eotteokaeyo",en:"Oh no, what do we do",pos:"expression"},sentence:{ko:"A: 지갑을 잃어버렸어요. / B: 어머, 어떡해요!",en:"A: I lost my wallet. / B: Oh my, that's awful!"},target:"어떡해요",options:["Oh no, what do we do","Really?! / for real? — surprised, more colloquial and emotional than 정말요.","Really? — a polite check that you heard right, mild surprise or interest."],note:""}]}],n={generatedFrom:e,snacks:o};export{n as default,e as generatedFrom,o as snacks};
